export const pages = {"delete-account.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Delete Account</title>\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body><main>\n<h1>Delete your Stormdrop Royale account</h1>\n<nav><a href=\"/\">Home</a><a href=\"/privacy\">Privacy</a></nav>\n<div class=\"card\">\n  <p><b>Fastest way:</b> open the Game → <b>Settings → Account → Delete account</b>. Deletion is immediate.</p>\n  <p><b>Uninstalled the Game?</b> Accounts that are not used for 30 days are deleted automatically — you don't need to do anything.</p>\n  <p>Can't open the Game? Send a request below. We verify it's your account by email and delete it within 30 days.</p>\n  <p class=\"dim\">What is deleted: sign-in links, nickname, friends, guild membership, chat messages, settings, push tokens, items and currencies.\n  What is kept: anonymised match statistics, and purchase records for as long as tax law requires.</p>\n</div>\n<form id=\"f\" class=\"card\">\n  <label for=\"tag\">Player ID (10 digits, shown in the lobby)</label>\n  <input id=\"tag\" name=\"playerTag\" inputmode=\"numeric\" pattern=\"\\d{6,12}\" required>\n  <label for=\"email\">Email we can reach you at</label>\n  <input id=\"email\" name=\"email\" type=\"email\" required>\n  <label for=\"reason\">Reason (optional)</label>\n  <textarea id=\"reason\" name=\"reason\" rows=\"3\"></textarea>\n  <button type=\"submit\">Request deletion</button>\n  <p id=\"msg\" class=\"dim\"></p>\n</form>\n<script>\ndocument.getElementById(\"f\").addEventListener(\"submit\", async (e) => {\n  e.preventDefault();\n  const msg = document.getElementById(\"msg\");\n  const body = Object.fromEntries(new FormData(e.target));\n  try {\n    const r = await fetch(\"/api/deletion-request\", { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify(body) });\n    const j = await r.json();\n    msg.textContent = r.ok ? \"Request received. We'll email you to confirm.\" : (j.error || \"Something went wrong\");\n    if (r.ok) e.target.reset();\n  } catch { msg.textContent = \"Network error, please try again.\"; }\n});\n</script>\n</main></body>\n</html>\n","index.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Stormdrop Royale</title>\n<meta name=\"description\" content=\"Stormdrop Royale – a fast 50-player mobile battle royale.\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body><main>\n<h1><span>Stormdrop</span> Royale</h1>\n<p class=\"dim\">50 players. One island. A storm that never stops closing in.</p>\n<nav><a href=\"/privacy\">Privacy Policy</a><a href=\"/terms\">Terms of Service</a><a href=\"/delete-account\">Delete your account</a></nav>\n\n<div class=\"card\">\n  <h2 style=\"margin-top:0\">Download for Android</h2>\n  <p>Install the latest test build (APK). On your phone allow <i>Install unknown apps</i> for your browser when asked.</p>\n  <a class=\"btn\" href=\"/download\">⬇ Download APK</a>\n  <p class=\"dim\" id=\"apk-note\"></p>\n</div>\n\n<div class=\"card\">\n  <h2 style=\"margin-top:0\">Server status</h2>\n  <table>\n    <tr><td>API</td><td id=\"s-api\">checking…</td></tr>\n    <tr><td>Database</td><td id=\"s-db\">checking…</td></tr>\n    <tr><td>Game tables</td><td id=\"s-tables\">–</td></tr>\n    <tr><td>Players</td><td id=\"s-players\">–</td></tr>\n    <tr><td>Match servers online</td><td id=\"s-servers\">–</td></tr>\n  </table>\n  <p class=\"dim\" id=\"s-time\"></p>\n</div>\n\n<div class=\"card\">\n  <p>Parachute onto a 4 km island, loot weapons and gear, and be the last squad standing in 10–15 minute matches.\n  Play Solo, Duo or Squad, fast 4v4 Clash Squad rounds, Team Deathmatch, or practise in the Training Ground.</p>\n</div>\n</main>\n<script>\nconst ok = (t) => `<span class=\"ok\">● ${t}</span>`, bad = (t) => `<span class=\"bad\">● ${t}</span>`;\nasync function refresh() {\n  const $ = (id) => document.getElementById(id);\n  try {\n    const h = await (await fetch(\"/api/health\", { cache: \"no-store\" })).json();\n    $(\"s-api\").innerHTML = ok(\"online\");\n    $(\"s-db\").innerHTML = h.database === \"connected\" ? ok(\"connected\") : bad(h.database);\n    $(\"s-tables\").innerHTML = (h.tables === \"ready\" || h.tables === \"created\") ? ok(\"ready\") : (h.tables ? bad(h.tables) : \"–\");\n    $(\"s-players\").textContent = h.players ?? \"–\";\n    $(\"s-servers\").textContent = h.serversOnline ?? \"–\";\n    if (h.apkConfigured === false) $(\"apk-note\").textContent = \"No APK published yet — see docs/SETUP.md (Build APK).\";\n  } catch {\n    $(\"s-api\").innerHTML = bad(\"offline\");\n  }\n  $(\"s-time\").textContent = \"Updated \" + new Date().toLocaleTimeString();\n}\nrefresh(); setInterval(refresh, 15000);\n</script>\n</body>\n</html>\n","privacy.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Privacy Policy</title>\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body><main>\n<h1>Privacy Policy</h1>\n<p class=\"dim\">Stormdrop Royale · Last updated: 18 November 2026</p>\n<nav><a href=\"/\">Home</a><a href=\"/terms\">Terms</a><a href=\"/delete-account\">Delete account</a></nav>\n\n<p>This policy explains what information <b>[Your Studio Name]</b> (\"we\") collects when you play Stormdrop Royale (the \"Game\"),\nhow we use it, and the choices you have. Contact: <a href=\"mailto:support@example.com\">support@example.com</a>.</p>\n\n<h2>1. Information we collect</h2>\n<table>\n<tr><th>Data</th><th>Why</th></tr>\n<tr><td>Account identifiers: a random guest ID created on your device, or your Google Play Games / Facebook account ID if you sign in with them</td><td>To create and restore your account</td></tr>\n<tr><td>Profile: nickname, avatar, player ID, region, guild membership, friends list</td><td>To show your profile to other players and run social features</td></tr>\n<tr><td>Gameplay data: matches, kills, damage, rank, missions, items you own</td><td>To run matches, progression, rankings and leaderboards</td></tr>\n<tr><td>Purchase records: product, order ID and purchase token from Google Play (we never receive your card details)</td><td>To deliver Diamonds, prevent fraud and handle refunds</td></tr>\n<tr><td>Guild and party chat messages, reports you send</td><td>To provide chat and keep the community safe</td></tr>\n<tr><td>Voice chat audio (only when you turn your microphone on)</td><td>Sent live to your teammates through our voice provider; we do not record or store it</td></tr>\n<tr><td>Device and diagnostic data: device model, OS version, crash logs, app instance ID, IP address</td><td>To connect you to game servers, fix crashes and measure performance</td></tr>\n<tr><td>Push notification token</td><td>To send optional notifications (events, rewards)</td></tr>\n<tr><td>Anti-cheat signals: server-side checks of movement and shots</td><td>To detect cheating and protect fair play</td></tr>\n</table>\n<p>We do not collect your precise location, contacts, photos or files, and we do not sell your personal information.</p>\n\n<h2>2. Service providers</h2>\n<p>We share data only with providers that help us run the Game, under contracts that limit their use of it:\nGoogle (Play Games sign-in, Play Billing, Firebase Analytics, Crashlytics and Cloud Messaging),\nMeta (Facebook Login, only if you choose it), Unity Technologies (Vivox voice chat),\nSupabase (database hosting) and Vercel (API hosting). We may disclose data if required by law.</p>\n\n<h2>3. Retention</h2>\n<p>We keep your account data while you use the Game. <b>If you do not open the Game for 30 days — for example because you uninstalled it — your account and all its data are permanently deleted automatically.</b> Linking Google or Facebook does not prevent this. Purchase records are kept as long as tax and accounting laws require.\nChat messages are deleted after 30 days. Crash and analytics data is kept according to Firebase's retention settings (maximum 14 months).</p>\n\n<h2>4. Deleting your account</h2>\n<p>You can delete your account at any time in the Game: <b>Settings → Account → Delete account</b>. This erases your sign-in links, friends, guild membership, chat messages, settings and push tokens immediately, and the rest of your account is permanently removed by our daily deletion job (within 24 hours).\nIf you can no longer open the Game, use the <a href=\"/delete-account\">account deletion request form</a>; we process requests within 30 days.</p>\n\n<h2>5. Children</h2>\n<p>The Game is intended for players aged 13 and over and is not directed at children under 13. If you believe a child under 13 has\ncreated an account, contact us and we will delete it.</p>\n\n<h2>6. Your rights</h2>\n<p>Depending on where you live (for example under GDPR in the EU/UK or the DPDP Act in India) you may have the right to access,\ncorrect, delete or export your data, and to object to certain processing. Email us to make a request.</p>\n\n<h2>7. Security</h2>\n<p>All traffic between the Game and our servers is encrypted (HTTPS/TLS). Database access is restricted to our servers.</p>\n\n<h2>8. Changes</h2>\n<p>We will post changes on this page and update the date above. Significant changes will also be announced in the Game.</p>\n</main></body>\n</html>\n","style.css":":root { --bg:#0e1118; --panel:#171c26; --text:#eef1f6; --dim:#9aa4b5; --accent:#ff8c1a; --link:#5cc8ff; }\n@media (prefers-color-scheme: light) { :root:not([data-theme=\"dark\"]) { --bg:#f6f7fa; --panel:#fff; --text:#141821; --dim:#5b6475; --link:#0a6fb8; } }\n* { box-sizing: border-box; }\nbody { margin:0; background:var(--bg); color:var(--text); font:16px/1.6 system-ui,-apple-system,Segoe UI,Roboto,sans-serif; }\nmain { max-width: 820px; margin: 0 auto; padding: 32px 16px 64px; }\nh1 { font-size: 2rem; margin: 0 0 4px; } h1 span { color: var(--accent); }\nh2 { margin-top: 2rem; font-size: 1.2rem; }\np, li { color: var(--text); } .dim { color: var(--dim); }\na { color: var(--link); }\nnav { display:flex; gap:16px; flex-wrap:wrap; margin: 8px 0 24px; }\n.card { background: var(--panel); border-radius: 12px; padding: 20px; margin: 16px 0; }\nlabel { display:block; margin: 12px 0 4px; font-weight: 600; }\ninput, textarea { width:100%; padding:10px; border-radius:8px; border:1px solid #444b; background:var(--bg); color:var(--text); font:inherit; }\nbutton { margin-top:16px; background:var(--accent); color:#111; border:0; border-radius:8px; padding:12px 20px; font-weight:700; font-size:1rem; cursor:pointer; }\ntable { border-collapse: collapse; width: 100%; } td, th { text-align:left; padding:6px 8px; border-bottom:1px solid #8883; vertical-align: top; }\n.btn { display:inline-block; background:var(--accent); color:#111; text-decoration:none; font-weight:700; padding:12px 22px; border-radius:8px; }\n.ok { color:#2fbf5b; font-weight:600; } .bad { color:#e5484d; font-weight:600; }\n","terms.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Terms of Service</title>\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body><main>\n<h1>Terms of Service</h1>\n<p class=\"dim\">Stormdrop Royale · Last updated: 18 November 2026</p>\n<nav><a href=\"/\">Home</a><a href=\"/privacy\">Privacy</a><a href=\"/delete-account\">Delete account</a></nav>\n\n<h2>1. Agreement</h2>\n<p>By playing Stormdrop Royale you agree to these terms with <b>[Your Studio Name]</b>. You must be at least 13 years old.\nIf you are under the age of majority where you live, a parent or guardian must agree on your behalf.</p>\n\n<h2>2. Your account</h2>\n<p>Keep your login secure. Guest accounts are tied to your device; link Google or Facebook in Settings so you don't lose progress. Accounts that are not used for 30 days are permanently deleted, including items and Diamonds.\nOne account per person; do not buy, sell or share accounts.</p>\n\n<h2>3. Fair play</h2>\n<p>Cheating, hacking, modified clients, exploiting bugs, teaming with enemies, harassment, hate speech and offensive names are not allowed.\nOur servers check movement and shots automatically. We may suspend or ban accounts that break these rules, without refund of virtual items.</p>\n\n<h2>4. Virtual items and currency</h2>\n<p>Gold and Diamonds are virtual currencies with no real-world value. They and all virtual items are licensed to you, not sold, cannot be\nexchanged for money, and cannot be transferred outside the Game. Purchases are processed by Google Play and are subject to Google Play's refund policy.\nFortune Drop rewards are random; the odds of every reward are shown in the Game before you spend Diamonds.</p>\n\n<h2>5. Content</h2>\n<p>The Game, its characters, art and code belong to [Your Studio Name]. Chat and nicknames you create must follow these terms; we may remove them.</p>\n\n<h2>6. Service changes</h2>\n<p>We may update, change or discontinue features, events or the Game. Online features need an internet connection and may be unavailable at times.</p>\n\n<h2>7. Disclaimers and liability</h2>\n<p>The Game is provided \"as is\". To the extent allowed by law, we are not liable for indirect or consequential losses. Nothing in these terms\nlimits rights you have under consumer protection laws in your country.</p>\n\n<h2>8. Contact</h2>\n<p><a href=\"mailto:support@example.com\">support@example.com</a></p>\n</main></body>\n</html>\n"};
export const schemaSql = "-- =====================================================================\n-- Stormdrop Royale — database schema (Supabase / Postgres)\n-- Run once:  npm run db:setup   (or paste into Supabase → SQL Editor)\n-- Safe to re-run: every statement is idempotent.\n--\n-- Security model (same as before): Row Level Security is ON for every\n-- table with NO public policies, so only the backend (which connects\n-- with the database password) can read or write. Game clients never\n-- talk to the database directly — they go through the API.\n-- =====================================================================\n\ncreate extension if not exists pgcrypto;\n\n-- Old Stock Analyzer tables. Uncomment to remove them once you no longer need the data.\n-- drop table if exists watchlist, alerts, price_history, signal_history cascade;\n\n-- ---------------------------------------------------------------- accounts\ncreate table if not exists players (\n  id               uuid primary key default gen_random_uuid(),\n  player_tag       text unique not null,                 -- public numeric ID shown in game\n  nickname         text not null,\n  avatar_id        text not null default 'avatar_default',\n  banner_id        text not null default 'banner_default',\n  region           text not null default 'IND',          -- matchmaking region\n  level            int  not null default 1,\n  xp               int  not null default 0,\n  gold             bigint not null default 0 check (gold >= 0),\n  diamonds         bigint not null default 0 check (diamonds >= 0),\n  br_rank_points   int  not null default 0,              -- battle royale ranked\n  cs_rank_points   int  not null default 0,              -- clash squad ranked\n  br_season_best   int  not null default 0,\n  guild_id         uuid,\n  is_banned        boolean not null default false,\n  ban_reason       text,\n  created_at       timestamptz not null default now(),\n  last_login_at    timestamptz not null default now(),\n  last_active_at   timestamptz not null default now(),   -- any API use; drives the 30-day inactivity deletion\n  deleted_at       timestamptz\n);\nalter table players add column if not exists last_active_at timestamptz not null default now();\ncreate index if not exists players_last_active_idx on players (last_active_at);\ncreate index if not exists players_br_rank_idx on players (region, br_rank_points desc) where deleted_at is null;\ncreate index if not exists players_nickname_idx on players (lower(nickname));\n\n-- One player can be linked to several login providers (guest, google, facebook)\ncreate table if not exists auth_identities (\n  provider      text not null check (provider in ('guest','google','facebook','apple')),\n  provider_uid  text not null,\n  player_id     uuid not null references players(id) on delete cascade,\n  created_at    timestamptz not null default now(),\n  primary key (provider, provider_uid)\n);\ncreate index if not exists auth_identities_player_idx on auth_identities (player_id);\n\ncreate table if not exists player_settings (\n  player_id   uuid primary key references players(id) on delete cascade,\n  data        jsonb not null default '{}'::jsonb,       -- HUD layout, sensitivity, graphics\n  updated_at  timestamptz not null default now()\n);\n\ncreate table if not exists push_tokens (\n  token       text primary key,\n  player_id   uuid not null references players(id) on delete cascade,\n  platform    text not null default 'android',\n  updated_at  timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------- catalog & inventory\ncreate table if not exists items (\n  id              text primary key,                     -- e.g. char_kael, skin_raptor_neon\n  type            text not null check (type in ('character','pet','weapon_skin','outfit','emote',\n                                                 'parachute','vehicle_skin','avatar','banner',\n                                                 'consumable','currency','pass_xp')),\n  name            text not null,\n  rarity          text not null default 'common' check (rarity in ('common','rare','epic','legendary','mythic')),\n  description     text not null default '',\n  price_gold      int,                                  -- null = not buyable with gold\n  price_diamonds  int,                                  -- null = not buyable with diamonds\n  in_store        boolean not null default true,\n  metadata        jsonb not null default '{}'::jsonb,   -- skill id, weapon id for skins, etc.\n  sort_order      int not null default 0,\n  created_at      timestamptz not null default now()\n);\n\ncreate table if not exists player_items (\n  player_id    uuid not null references players(id) on delete cascade,\n  item_id      text not null references items(id),\n  quantity     int  not null default 1 check (quantity >= 0),\n  acquired_at  timestamptz not null default now(),\n  expires_at   timestamptz,                             -- null = permanent\n  primary key (player_id, item_id)\n);\n\ncreate table if not exists loadouts (\n  player_id     uuid primary key references players(id) on delete cascade,\n  character_id  text not null default 'char_kael' references items(id),\n  pet_id        text references items(id),\n  parachute_id  text references items(id),\n  outfit        jsonb not null default '{}'::jsonb,     -- slot -> item id\n  weapon_skins  jsonb not null default '{}'::jsonb,     -- weapon id -> skin item id\n  emotes        jsonb not null default '[]'::jsonb,\n  updated_at    timestamptz not null default now()\n);\n\n-- Every change to gold/diamonds is written here (audit trail, refunds, fraud checks)\ncreate table if not exists currency_ledger (\n  id          bigserial primary key,\n  player_id   uuid not null references players(id) on delete cascade,\n  currency    text not null check (currency in ('gold','diamonds')),\n  delta       bigint not null,\n  reason      text not null,\n  ref         text,\n  created_at  timestamptz not null default now()\n);\ncreate index if not exists currency_ledger_player_idx on currency_ledger (player_id, created_at desc);\n\n-- Real-money purchases (Google Play / App Store)\ncreate table if not exists purchases (\n  id              uuid primary key default gen_random_uuid(),\n  player_id       uuid references players(id) on delete set null,   -- kept (anonymised) for tax records\n  platform        text not null check (platform in ('google_play','app_store')),\n  product_id      text not null,\n  order_id        text,\n  purchase_token  text not null unique,\n  diamonds        int  not null default 0,\n  status          text not null default 'credited' check (status in ('credited','refunded','rejected')),\n  raw             jsonb,\n  created_at      timestamptz not null default now()\n);\n\n-- Older databases: keep purchase rows when an account is deleted\nalter table purchases alter column player_id drop not null;\nalter table purchases drop constraint if exists purchases_player_id_fkey;\nalter table purchases add constraint purchases_player_id_fkey foreign key (player_id) references players(id) on delete set null;\n\n-- ---------------------------------------------------------------- social\ncreate table if not exists friendships (\n  player_id   uuid not null references players(id) on delete cascade,\n  friend_id   uuid not null references players(id) on delete cascade,\n  status      text not null check (status in ('pending','accepted')),   -- pending = player_id asked friend_id\n  created_at  timestamptz not null default now(),\n  primary key (player_id, friend_id),\n  check (player_id <> friend_id)\n);\n\ncreate table if not exists parties (\n  id          uuid primary key default gen_random_uuid(),\n  leader_id   uuid not null references players(id) on delete cascade,\n  mode        text not null default 'br_squad',\n  created_at  timestamptz not null default now()\n);\ncreate table if not exists party_members (\n  player_id   uuid primary key references players(id) on delete cascade,   -- a player is in at most one party\n  party_id    uuid not null references parties(id) on delete cascade,\n  joined_at   timestamptz not null default now()\n);\ncreate table if not exists party_invites (\n  party_id    uuid not null references parties(id) on delete cascade,\n  player_id   uuid not null references players(id) on delete cascade,\n  invited_by  uuid not null references players(id) on delete cascade,\n  created_at  timestamptz not null default now(),\n  primary key (party_id, player_id)\n);\n\ncreate table if not exists guilds (\n  id           uuid primary key default gen_random_uuid(),\n  name         text not null unique,\n  tag          text not null unique check (char_length(tag) between 2 and 5),\n  description  text not null default '',\n  leader_id    uuid not null references players(id),\n  level        int  not null default 1,\n  glory        bigint not null default 0,\n  max_members  int  not null default 30,\n  min_level    int  not null default 1,\n  created_at   timestamptz not null default now()\n);\ncreate table if not exists guild_members (\n  player_id   uuid primary key references players(id) on delete cascade,\n  guild_id    uuid not null references guilds(id) on delete cascade,\n  role        text not null default 'member' check (role in ('leader','officer','member')),\n  joined_at   timestamptz not null default now()\n);\ncreate index if not exists guild_members_guild_idx on guild_members (guild_id);\n\n-- Quick-chat and text messages (party / guild). Voice goes through the voice service, not the DB.\ncreate table if not exists chat_messages (\n  id          bigserial primary key,\n  channel     text not null,                -- 'guild:<id>' or 'party:<id>'\n  player_id   uuid not null references players(id) on delete cascade,\n  body        text not null check (char_length(body) <= 200),\n  created_at  timestamptz not null default now()\n);\ncreate index if not exists chat_messages_channel_idx on chat_messages (channel, id desc);\n\n-- ---------------------------------------------------------------- matchmaking & matches\ncreate table if not exists game_servers (\n  id               uuid primary key default gen_random_uuid(),\n  region           text not null,\n  host             text not null,\n  port             int  not null,\n  version          text not null default '1.0.0',\n  status           text not null default 'ready' check (status in ('ready','allocated','in_match','offline')),\n  current_match_id uuid,\n  max_players      int  not null default 50,\n  last_heartbeat   timestamptz not null default now(),\n  unique (host, port)\n);\n\ncreate table if not exists matches (\n  id           uuid primary key default gen_random_uuid(),\n  mode         text not null check (mode in ('br_solo','br_duo','br_squad','clash_squad','tdm','training')),\n  region       text not null,\n  is_ranked    boolean not null default false,\n  map_id       text not null default 'isle_verdant',\n  time_of_day  text not null default 'day' check (time_of_day in ('day','night')),\n  server_id    uuid references game_servers(id) on delete set null,\n  status       text not null default 'allocated' check (status in ('allocated','running','finished','abandoned')),\n  winner_team  int,\n  created_at   timestamptz not null default now(),\n  started_at   timestamptz,\n  ended_at     timestamptz\n);\n\ncreate table if not exists matchmaking_tickets (\n  id           uuid primary key default gen_random_uuid(),\n  player_id    uuid not null references players(id) on delete cascade,\n  party_id     uuid,\n  mode         text not null,\n  region       text not null,\n  is_ranked    boolean not null default false,\n  rank_points  int  not null default 0,\n  status       text not null default 'waiting' check (status in ('waiting','matched','cancelled','expired')),\n  match_id     uuid references matches(id) on delete set null,\n  team         int,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\ncreate index if not exists mm_waiting_idx on matchmaking_tickets (mode, region, is_ranked, created_at) where status = 'waiting';\ncreate unique index if not exists mm_one_active_ticket on matchmaking_tickets (player_id) where status = 'waiting';\n\ncreate table if not exists match_players (\n  match_id          uuid not null references matches(id) on delete cascade,\n  player_id         uuid not null references players(id) on delete cascade,\n  team              int  not null,\n  character_id      text,\n  placement         int,\n  kills             int not null default 0,\n  assists           int not null default 0,\n  damage            int not null default 0,\n  headshots         int not null default 0,\n  revives           int not null default 0,\n  survival_seconds  int not null default 0,\n  rank_delta        int not null default 0,\n  xp_gained         int not null default 0,\n  gold_gained       int not null default 0,\n  suspicious        boolean not null default false,  -- flagged by server-side anti-cheat\n  primary key (match_id, player_id)\n);\ncreate index if not exists match_players_player_idx on match_players (player_id);\n\ncreate table if not exists player_stats (\n  player_id   uuid not null references players(id) on delete cascade,\n  mode        text not null,\n  matches     int not null default 0,\n  wins        int not null default 0,\n  top10       int not null default 0,\n  kills       int not null default 0,\n  deaths      int not null default 0,\n  damage      bigint not null default 0,\n  headshots   int not null default 0,\n  primary key (player_id, mode)\n);\n\ncreate table if not exists reports (\n  id           uuid primary key default gen_random_uuid(),\n  reporter_id  uuid references players(id) on delete set null,\n  reported_id  uuid not null references players(id) on delete cascade,\n  match_id     uuid references matches(id) on delete set null,\n  reason       text not null check (reason in ('cheating','teaming','abuse','name','afk','other')),\n  details      text,\n  source       text not null default 'player' check (source in ('player','anticheat')),\n  status       text not null default 'open' check (status in ('open','reviewed','actioned','dismissed')),\n  created_at   timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------- progression\ncreate table if not exists mission_defs (\n  id              text primary key,\n  period          text not null check (period in ('daily','weekly')),\n  title           text not null,\n  metric          text not null check (metric in ('matches','kills','damage','top10','wins','revives','headshots','survival_minutes')),\n  target          int  not null,\n  reward_xp       int  not null default 0,\n  reward_gold     int  not null default 0,\n  reward_diamonds int  not null default 0,\n  reward_pass_xp  int  not null default 0,\n  active          boolean not null default true\n);\ncreate table if not exists player_missions (\n  player_id    uuid not null references players(id) on delete cascade,\n  mission_id   text not null references mission_defs(id),\n  period_key   text not null,               -- '2026-11-18' for daily, '2026-W47' for weekly\n  progress     int  not null default 0,\n  claimed_at   timestamptz,\n  primary key (player_id, mission_id, period_key)\n);\n\ncreate table if not exists achievement_defs (\n  id               text primary key,\n  title            text not null,\n  metric           text not null,\n  target           int  not null,\n  reward_gold      int  not null default 0,\n  reward_diamonds  int  not null default 0\n);\ncreate table if not exists player_achievements (\n  player_id       uuid not null references players(id) on delete cascade,\n  achievement_id  text not null references achievement_defs(id),\n  progress        int  not null default 0,\n  completed_at    timestamptz,\n  claimed_at      timestamptz,\n  primary key (player_id, achievement_id)\n);\n\n-- Storm Pass (battle pass): free + premium track\ncreate table if not exists pass_seasons (\n  id                      text primary key,\n  name                    text not null,\n  starts_at               timestamptz not null,\n  ends_at                 timestamptz not null,\n  premium_price_diamonds  int not null default 499,\n  xp_per_level            int not null default 1000,\n  max_level               int not null default 50\n);\ncreate table if not exists pass_rewards (\n  season_id  text not null references pass_seasons(id) on delete cascade,\n  level      int  not null,\n  track      text not null check (track in ('free','premium')),\n  item_id    text not null references items(id),\n  quantity   int  not null default 1,\n  primary key (season_id, level, track)\n);\ncreate table if not exists player_pass (\n  player_id   uuid not null references players(id) on delete cascade,\n  season_id   text not null references pass_seasons(id) on delete cascade,\n  pass_xp     int  not null default 0,\n  premium     boolean not null default false,\n  claimed     jsonb not null default '[]'::jsonb,       -- [\"1:free\",\"1:premium\",...]\n  primary key (player_id, season_id)\n);\n\n-- Fortune Drop (lucky spin). Odds are public — Google Play requires disclosing them.\ncreate table if not exists spin_events (\n  id               text primary key,\n  name             text not null,\n  starts_at        timestamptz not null,\n  ends_at          timestamptz not null,\n  cost_single      int not null default 20,      -- diamonds\n  cost_ten         int not null default 180,\n  active           boolean not null default true\n);\ncreate table if not exists spin_rewards (\n  event_id   text not null references spin_events(id) on delete cascade,\n  item_id    text not null references items(id),\n  quantity   int  not null default 1,\n  weight     int  not null check (weight > 0),\n  primary key (event_id, item_id)\n);\ncreate table if not exists spin_history (\n  id          bigserial primary key,\n  player_id   uuid not null references players(id) on delete cascade,\n  event_id    text not null references spin_events(id) on delete cascade,\n  item_id     text not null references items(id),\n  quantity    int  not null,\n  created_at  timestamptz not null default now()\n);\n\ncreate table if not exists login_reward_defs (\n  day       int primary key check (day between 1 and 7),\n  item_id   text not null references items(id),\n  quantity  int  not null default 1\n);\ncreate table if not exists player_login_rewards (\n  player_id        uuid primary key references players(id) on delete cascade,\n  streak_day       int  not null default 0,\n  last_claim_date  date\n);\n\ncreate table if not exists game_events (\n  id           text primary key,\n  title        text not null,\n  description  text not null default '',\n  type         text not null default 'news' check (type in ('news','double_xp','top_up','mode','spin','tournament')),\n  banner_url   text,\n  starts_at    timestamptz not null,\n  ends_at      timestamptz not null,\n  data         jsonb not null default '{}'::jsonb\n);\n\n-- Account deletion requests from the public web form (Google Play requirement)\ncreate table if not exists deletion_requests (\n  id             uuid primary key default gen_random_uuid(),\n  player_tag     text not null,\n  contact_email  text not null,\n  reason         text,\n  status         text not null default 'open' check (status in ('open','done','rejected')),\n  created_at     timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------- leaderboard view\ncreate or replace view leaderboard_br as\n  select p.id as player_id, p.player_tag, p.nickname, p.avatar_id, p.region, p.level,\n         p.br_rank_points, g.tag as guild_tag,\n         rank() over (partition by p.region order by p.br_rank_points desc) as region_rank\n  from players p\n  left join guilds g on g.id = p.guild_id\n  where p.deleted_at is null and p.is_banned = false;\n\n-- ---------------------------------------------------------------- row level security\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array[\n    'players','auth_identities','player_settings','push_tokens','items','player_items','loadouts',\n    'currency_ledger','purchases','friendships','parties','party_members','party_invites','guilds',\n    'guild_members','chat_messages','game_servers','matches','matchmaking_tickets','match_players',\n    'player_stats','reports','mission_defs','player_missions','achievement_defs','player_achievements',\n    'pass_seasons','pass_rewards','player_pass','spin_events','spin_rewards','spin_history',\n    'login_reward_defs','player_login_rewards','game_events','deletion_requests']\n  loop\n    execute format('alter table %I enable row level security', t);\n  end loop;\nend $$;\n\n-- The view runs with the caller's rights so RLS still applies through it\nalter view leaderboard_br set (security_invoker = true);\n\n-- ---------------------------------------------------------------- automatic account deletion\n-- Permanently deletes (1) accounts not used for `inactive_days` days — e.g. the player uninstalled\n-- the app — and (2) accounts the player deleted in the app. Guild leadership passes to another\n-- member; purchase records are kept without the player link (tax law). Runs daily (see db/jobs.sql\n-- and the /api/cron/cleanup Vercel cron). Returns the number of accounts deleted.\ncreate or replace function purge_inactive_players(inactive_days int default 30)\nreturns int language plpgsql security definer set search_path = public as $$\ndeclare victims uuid[]; n int;\nbegin\n  select array_agg(id) into victims from players\n   where deleted_at is not null or last_active_at < now() - make_interval(days => inactive_days);\n  if victims is null then return 0; end if;\n\n  -- hand guild leadership to a remaining member (officers first), otherwise the guild is removed\n  update guilds g set leader_id = x.next_leader\n  from (select distinct on (gm.guild_id) gm.guild_id, gm.player_id as next_leader\n        from guild_members gm where gm.player_id <> all(victims)\n        order by gm.guild_id, case gm.role when 'officer' then 0 else 1 end, gm.joined_at) x\n  where g.id = x.guild_id and g.leader_id = any(victims);\n  update guild_members gm set role = 'leader' from guilds g\n   where g.id = gm.guild_id and g.leader_id = gm.player_id and gm.role <> 'leader';\n  update players set guild_id = null where guild_id in (select id from guilds where leader_id = any(victims));\n  delete from guilds where leader_id = any(victims);\n\n  delete from players where id = any(victims);   -- everything else cascades\n  get diagnostics n = row_count;\n  return n;\nend $$;\n-- Only the backend/database owner may run it (never exposed through the public Supabase API)\nrevoke execute on function purge_inactive_players(int) from public;\ndo $$ begin\n  if exists (select 1 from pg_roles where rolname = 'anon') then\n    execute 'revoke execute on function purge_inactive_players(int) from anon, authenticated';\n  end if;\nend $$;\n";
export const seedSql = "-- =====================================================================\n-- Stormdrop Royale — starter content. Safe to re-run (upserts).\n-- Character/pet ids here must match CharacterData/PetData ids in Unity.\n-- =====================================================================\n\n-- ---------------------------------------------------------------- characters (12)\ninsert into items (id, type, name, rarity, description, price_gold, price_diamonds, metadata, sort_order) values\n ('char_kael',  'character','Kael',  'common',   'Active – Sprint Surge: +30% move speed for 6 s (CD 45 s).',            null, null, '{\"skill\":\"sprint_surge\",\"default\":true}', 1),\n ('char_mira',  'character','Mira',  'rare',     'Passive – Field Medic: healing items work 30% faster and heal +15%.',  8000,  399, '{\"skill\":\"field_medic\"}', 2),\n ('char_torvin','character','Torvin','epic',     'Active – Bastion Dome: shield absorbing 120 damage for 5 s (CD 60 s).',null,  499, '{\"skill\":\"bastion_dome\"}', 3),\n ('char_zara',  'character','Zara',  'rare',     'Passive – Ghost Step: footsteps are silent while crouched or prone.',  8000,  399, '{\"skill\":\"ghost_step\"}', 4),\n ('char_okoro', 'character','Okoro', 'epic',     'Active – Healing Aura: heals you and allies within 5 m for 6 HP/s, 5 s (CD 50 s).', null, 499, '{\"skill\":\"healing_aura\"}', 5),\n ('char_lyra',  'character','Lyra',  'rare',     'Passive – Eagle Eye: enemies you hit are marked for your squad for 3 s.', 8000, 399, '{\"skill\":\"eagle_eye\"}', 6),\n ('char_dante', 'character','Dante', 'rare',     'Passive – Iron Skin: take 8% less damage from bullets.',                8000,  399, '{\"skill\":\"iron_skin\"}', 7),\n ('char_suki',  'character','Suki',  'epic',     'Active – Blink Dash: dash 7 m in the move direction (CD 30 s).',        null,  499, '{\"skill\":\"blink_dash\"}', 8),\n ('char_rook',  'character','Rook',  'common',   'Passive – Scavenger: knocking an enemy restores 25 HP.',                6000,  299, '{\"skill\":\"scavenger\"}', 9),\n ('char_nova',  'character','Nova',  'legendary','Active – Pulse Scan: reveals enemies within 50 m for 3 s (CD 75 s).',  null,  699, '{\"skill\":\"pulse_scan\"}', 10),\n ('char_bram',  'character','Bram',  'common',   'Passive – Quick Hands: reload 20% faster.',                             6000,  299, '{\"skill\":\"quick_hands\"}', 11),\n ('char_ivy',   'character','Ivy',   'rare',     'Passive – Vigor Bloom: Vigor Shrooms give 50% more energy.',           8000,  399, '{\"skill\":\"vigor_bloom\"}', 12)\non conflict (id) do update set name=excluded.name, rarity=excluded.rarity, description=excluded.description,\n  price_gold=excluded.price_gold, price_diamonds=excluded.price_diamonds, metadata=excluded.metadata, sort_order=excluded.sort_order;\n\n-- ---------------------------------------------------------------- pets (4)\ninsert into items (id, type, name, rarity, description, price_gold, price_diamonds, metadata, sort_order) values\n ('pet_ember', 'pet','Ember the Fox',     'rare', 'Takes 50% less fall and landing damage.',            null, 299, '{\"buff\":\"soft_landing\"}', 20),\n ('pet_byte',  'pet','Byte the Owl',      'epic', 'Pings enemies who shoot within 30 m of you.',        null, 499, '{\"buff\":\"gunfire_ping\"}', 21),\n ('pet_pebble','pet','Pebble the Turtle', 'rare', 'Repairs 1 vest durability every 4 s out of combat.', null, 299, '{\"buff\":\"armor_mend\"}', 22),\n ('pet_dash',  'pet','Dash the Ferret',   'common','Loot pickup and door use 20% faster.',              5000, 199, '{\"buff\":\"quick_paws\"}', 23)\non conflict (id) do update set name=excluded.name, description=excluded.description, price_gold=excluded.price_gold,\n  price_diamonds=excluded.price_diamonds, metadata=excluded.metadata;\n\n-- ---------------------------------------------------------------- cosmetics\ninsert into items (id, type, name, rarity, description, price_gold, price_diamonds, metadata, sort_order) values\n ('skin_raptor_neon',   'weapon_skin','Raptor-7 Neon Pulse',     'epic',     'Glowing AR finish.',              null, 299, '{\"weapon\":\"ar_raptor7\"}', 30),\n ('skin_wasp_tiger',    'weapon_skin','Wasp SMG Tiger Stripe',   'rare',     'Orange camo for the Wasp.',       12000, 199, '{\"weapon\":\"smg_wasp\"}', 31),\n ('skin_longreach_frost','weapon_skin','Longreach Frostbite',    'legendary','Ice-crystal sniper skin.',        null, 599, '{\"weapon\":\"sr_longreach\"}', 32),\n ('skin_thunder_gold',  'weapon_skin','Thunderclap Gilded',      'epic',     'Gold-plated shotgun.',            null, 349, '{\"weapon\":\"sg_thunderclap\"}', 33),\n ('outfit_desert_ops',  'outfit','Desert Ops Set',              'rare',     'Sand-coloured tactical outfit.',   15000, 249, '{\"slot\":\"full\"}', 40),\n ('outfit_neon_runner', 'outfit','Neon Runner Set',             'legendary','Light-strip streetwear.',          null, 799, '{\"slot\":\"full\"}', 41),\n ('outfit_cap_storm',   'outfit','Storm Cap',                   'common',   'Basic cap.',                       3000, null, '{\"slot\":\"head\"}', 42),\n ('emote_victory_flip', 'emote','Victory Flip',                 'epic',     'Backflip celebration.',            null, 299, '{}', 50),\n ('emote_salute',       'emote','Salute',                       'common',   'Classic salute.',                  4000, 99, '{}', 51),\n ('emote_dance_wave',   'emote','Wave Dance',                   'rare',     'Smooth wave dance.',               null, 199, '{}', 52),\n ('chute_phoenix',      'parachute','Phoenix Wings',            'legendary','Fiery parachute trail.',           null, 499, '{}', 60),\n ('chute_classic_blue', 'parachute','Classic Blue',             'common',   'Simple blue canopy.',              5000, null, '{}', 61),\n ('veh_jeep_jungle',    'vehicle_skin','Jungle Jeep',           'rare',     'Camo jeep paint.',                 null, 249, '{\"vehicle\":\"jeep\"}', 70),\n ('veh_bike_chrome',    'vehicle_skin','Chrome Bike',           'epic',     'Mirror-finish motorbike.',         null, 349, '{\"vehicle\":\"motorbike\"}', 71),\n ('avatar_default',     'avatar','Rookie',                      'common',   '',                                 null, null, '{\"default\":true}', 80),\n ('banner_default',     'banner','Storm Grey',                  'common',   '',                                 null, null, '{\"default\":true}', 81)\non conflict (id) do update set name=excluded.name, rarity=excluded.rarity, description=excluded.description,\n  price_gold=excluded.price_gold, price_diamonds=excluded.price_diamonds, metadata=excluded.metadata;\n\n-- ---------------------------------------------------------------- currencies / consumables (rewards only)\ninsert into items (id, type, name, rarity, description, in_store, metadata, sort_order) values\n ('cur_gold_100',     'currency','100 Gold',        'common','', false, '{\"currency\":\"gold\",\"amount\":100}', 90),\n ('cur_gold_500',     'currency','500 Gold',        'common','', false, '{\"currency\":\"gold\",\"amount\":500}', 91),\n ('cur_gold_2000',    'currency','2,000 Gold',      'rare',  '', false, '{\"currency\":\"gold\",\"amount\":2000}', 92),\n ('cur_diamonds_10',  'currency','10 Diamonds',     'rare',  '', false, '{\"currency\":\"diamonds\",\"amount\":10}', 93),\n ('cur_diamonds_50',  'currency','50 Diamonds',     'epic',  '', false, '{\"currency\":\"diamonds\",\"amount\":50}', 94),\n ('card_xp_double',   'consumable','Double XP Card (1 h)', 'rare','', false, '{\"effect\":\"double_xp\",\"minutes\":60}', 95),\n ('card_name_change', 'consumable','Name Change Card','rare','', true,  '{\"effect\":\"rename\"}', 96),\n ('pass_xp_500',      'pass_xp','500 Pass XP',      'common','', false, '{\"amount\":500}', 97)\non conflict (id) do nothing;\nupdate items set price_diamonds = 99 where id = 'card_name_change';\n\n-- ---------------------------------------------------------------- missions\ninsert into mission_defs (id, period, title, metric, target, reward_xp, reward_gold, reward_diamonds, reward_pass_xp) values\n ('d_play_3',      'daily', 'Play 3 matches',                 'matches',          3,   300, 200, 0, 200),\n ('d_kills_5',     'daily', 'Eliminate 5 enemies',            'kills',            5,   300, 250, 0, 200),\n ('d_damage_1000', 'daily', 'Deal 1,000 damage',              'damage',        1000,   300, 250, 0, 200),\n ('d_survive_20',  'daily', 'Survive 20 minutes in total',    'survival_minutes',20,   200, 150, 0, 150),\n ('w_top10_10',    'weekly','Finish Top 10 ten times',         'top10',           10,  1500,1000, 10, 800),\n ('w_win_2',       'weekly','Become Storm Champion twice',     'wins',             2,  2000,1500, 20,1000),\n ('w_revive_10',   'weekly','Revive teammates 10 times',       'revives',         10,  1000, 800,  0, 600),\n ('w_head_25',     'weekly','Land 25 headshot eliminations',   'headshots',       25,  1500,1000, 10, 800)\non conflict (id) do update set title=excluded.title, target=excluded.target, reward_xp=excluded.reward_xp,\n  reward_gold=excluded.reward_gold, reward_diamonds=excluded.reward_diamonds, reward_pass_xp=excluded.reward_pass_xp;\n\ninsert into achievement_defs (id, title, metric, target, reward_gold, reward_diamonds) values\n ('a_first_win',  'First Storm Champion', 'wins',     1,   1000, 20),\n ('a_kills_100',  'Centurion',            'kills',  100,   2000, 30),\n ('a_kills_1000', 'Storm Legend',         'kills', 1000,  10000, 100),\n ('a_matches_50', 'Veteran Dropper',      'matches', 50,   2000, 20),\n ('a_revive_50',  'Guardian Angel',       'revives', 50,   3000, 30)\non conflict (id) do nothing;\n\n-- ---------------------------------------------------------------- Storm Pass season 1\ninsert into pass_seasons (id, name, starts_at, ends_at, premium_price_diamonds, xp_per_level, max_level)\nvalues ('s1', 'Season 1 – First Landing', '2026-11-01', '2027-01-31', 499, 1000, 50)\non conflict (id) do nothing;\n\ninsert into pass_rewards (season_id, level, track, item_id, quantity)\nselect 's1', lvl, 'free',\n       case when lvl % 10 = 0 then 'cur_diamonds_10' when lvl % 5 = 0 then 'card_xp_double' else 'cur_gold_100' end, 1\nfrom generate_series(1, 50) as lvl\non conflict do nothing;\n\ninsert into pass_rewards (season_id, level, track, item_id, quantity)\nselect 's1', lvl, 'premium',\n       case lvl when 1 then 'outfit_neon_runner' when 15 then 'skin_raptor_neon' when 30 then 'chute_phoenix'\n                when 50 then 'skin_longreach_frost'\n                else case when lvl % 4 = 0 then 'cur_diamonds_10' else 'cur_gold_500' end end, 1\nfrom generate_series(1, 50) as lvl\non conflict do nothing;\n\n-- ---------------------------------------------------------------- Fortune Drop (odds shown in game)\ninsert into spin_events (id, name, starts_at, ends_at, cost_single, cost_ten)\nvalues ('fd_phoenix', 'Phoenix Fortune Drop', '2026-11-01', '2027-01-31', 20, 180)\non conflict (id) do nothing;\n\ninsert into spin_rewards (event_id, item_id, quantity, weight) values\n ('fd_phoenix','chute_phoenix',      1,   10),   -- 1.0%\n ('fd_phoenix','skin_thunder_gold',  1,   20),   -- 2.0%\n ('fd_phoenix','emote_victory_flip', 1,   40),   -- 4.0%\n ('fd_phoenix','cur_diamonds_10',    1,  130),   -- 13.0%\n ('fd_phoenix','card_xp_double',     1,  200),   -- 20.0%\n ('fd_phoenix','cur_gold_500',       1,  300),   -- 30.0%\n ('fd_phoenix','cur_gold_100',       1,  300)    -- 30.0%\non conflict do nothing;\n\n-- ---------------------------------------------------------------- 7-day login rewards\ninsert into login_reward_defs (day, item_id, quantity) values\n (1,'cur_gold_500',1),(2,'card_xp_double',1),(3,'cur_gold_500',1),(4,'cur_diamonds_10',1),\n (5,'cur_gold_2000',1),(6,'emote_salute',1),(7,'cur_diamonds_50',1)\non conflict (day) do update set item_id=excluded.item_id, quantity=excluded.quantity;\n\n-- ---------------------------------------------------------------- events calendar\ninsert into game_events (id, title, description, type, starts_at, ends_at) values\n ('ev_launch',     'Launch Celebration', 'Log in for 7 days to claim 50 Diamonds.',   'news',      '2026-11-01','2026-12-31'),\n ('ev_double_xp',  'Double XP Weekend',   'All matches give 2x XP.',                  'double_xp', '2026-11-28','2026-11-30'),\n ('ev_night_mode', 'Night Raid',          'Night-time Isle Verdant in Squad mode.',   'mode',      '2026-12-05','2026-12-12')\non conflict (id) do nothing;\n";
